import re, math

# the "keyword" strategy many children are taught, written as a program
KEYWORDS = {"more": "+", "altogether": "+", "total": "+",
            "left": "-", "gave away": "-", "fewer": "-",
            "each": "x", "times": "x", "shared": "/"}

def keyword_solver(problem):
    numbers = [int(n) for n in re.findall(r"\d+", problem)]
    for word, op in KEYWORDS.items():
        if word in problem.lower():
            a, b = sorted(numbers, reverse=True)[:2]
            return eval(f"{a} {op.replace('x', '*')} {b}")
    return None

problems = [
    ("Priya has 5 more stickers than Arjun. Priya has 12. How many does Arjun have?", 12 - 5),
    ("Sam gave away 8 marbles and has 15 left. How many did he have at the start?", 15 + 8),
    ("Each box holds 6 eggs. How many boxes are needed for 45 eggs?", math.ceil(45 / 6)),
    ("Mia read 14 pages on Monday and 9 on Tuesday. How many pages altogether?", 14 + 9),
]
for text, correct in problems:
    guess = keyword_solver(text)
    verdict = "right" if guess == correct else "WRONG"
    print(f"keyword answer {guess:>5}   correct {correct:>3}   {verdict}")
